   "summary": "人民银行深圳市分行公示（深人银罚〔2026〕18-19号）：招联违反信用信息采集、提供、查询及相关管理规定被罚18.5万元，时任营运中心员工祁某瑗被罚2.5万元；招联上半年总资产1473.56亿降11.89%、营收66.88亿降15.33%、净利13.81亿降8.18%。",
