   "summary": "招联消费金融在“双11”推出受邀用户抢最高30天免息券（单笔借款2万元内可用），并协同股东中国联通打造“联通白条”，以“国补+满减+分期”助力新就业群体购置手机、办理宽带等刚需消费。",
