   "title": "招联消费金融被罚18.5万元：违反信用信息采集、提供、查询管理规定",
   "summary": "中国人民银行深圳市分行公示，招联消费金融因违反信用信息采集、提供、查询及相关管理规定被罚款18.5万元，时任营运中心祁某瑗被罚2.5万元。这是消金行业强监管持续落地的具体案例。",
   "decision": "招联自身合规红线案例，与启停机制V3.0“合规四方牵制”高度相关，应作为代理商/合作方信用信息合规的镜鉴，避免类似处罚。",
