   "title": "央行政策利率正式“换锚”：11月2日起每个工作日开展隔夜逆回购招标，利率1.25%",
   "summary": "央行公告自11月2日起，每个工作日开展隔夜逆回购操作招标（固定利率、数量招标，利率1.25%），原7天期逆回购利率切换为隔夜逆回购利率成为主要政策利率。招联首席经济学家董希淼指出，此举缩短政策利率向货币市场、债券收益率和信贷利率的传导链条，提高调控效率。",
   "decision": "政策利率短端化、资金利率中枢有望更稳，直接影响招联等消金机构的同业融资成本与消费信贷定价，可关注DR001走势对资产端定价的传导。",
   "source": "人民网财经",
   "url": "https://finance.people.com.cn/n1/2026/1101/c1004-40825357.html",
