   "summary": "据财联社，一家国有超大型银行近日计划向中国国新、中国诚通两家央企新增股票回购增持贷款额度，单家新增额度或达1000亿元，规模或超2024年该工具设立时首期额度。",
   "decision": "回购增持再贷款扩容直接利好央企估值与资本市场稳定，招联可关注联通体系内资本运作与股东协同机会。",
