   "title": "国有大行及股份行集体公示个人贷款综合融资成本上限",
   "summary": "随《个人贷款业务明示综合融资成本规定》施行，国有六大行及多家股份制银行已于7月31日集体公示个人贷款综合融资成本上限，要求逐项列明息费项目及收取主体，助贷盈利模型面临调整。",
   "decision": "利率透明化压降消金利差空间，呼应“拼健康”趋势；招联定价与披露体系需确保合规，避免被监管点名。",
