   "title": "金融街论坛：潘功胜提出设立非银机构流动性支持工具等五项举措",
   "summary": "2026金融街论坛上，央行行长潘功胜提出五方面政策举措，核心是设立应对非银机构大额赎回的流动性支持工具，并推进银行间与交易所债券市场互联互通、外汇市场开放和科技金融支持等改革。",
   "decision": "流动性支持工具与债券市场互联互通有助于稳定资金面，利好招联等持牌消金的融资环境与流动性管理。",
