   "title": "助贷“白名单”落地一年：46家合作机构中33家暂停投放，准入持续收紧",
   "summary": "中新经纬报道，助贷新规施行一年后，银行合作机构白名单显著收敛，部分银行46家合作机构中33家已“暂停投放”。留存多为大型互联网平台旗下机构、头部民营银行与持牌消金，中腰部渠道被出清。",
   "decision": "招联作为头部持牌消金处受益方，但需警惕合作集中度上升；启停机制应把“代理商预算集中度超标”作为重点监控项。",
