   "title": "互金协会明确：花呗、白条、月付等专属金融产品须与互联网平台品牌隔离",
   "summary": "中国互联网金融协会10月31日发布落实问答，要求“花呗”“白条”“月付”“借呗”等作为金融机构专属产品由持牌机构提供，与相应互联网平台实现品牌隔离；第三方平台不得以自身名义在其他平台营销金融产品。",
   "decision": "网络营销管理办法落地，直接影响消金获客与助贷渠道合规，招联×联通合作及代理商标识管理需同步对齐品牌隔离要求。",
