   "summary": "截至10月31日，沪深两市5224家上市公司披露三季报，前三季度营收56.6万亿元、净利润5.1万亿元，同比分别+5.8%、+8.5%，73%公司盈利，滚动ROE为7.9%，规模与增速均创2022年以来新高。",
   "decision": "上市银行与券商盈利改善，招联股东侧（招行/联通）基本面稳健，利于招联在股东协同下的业务拓展。",
