   "title": "10月制造业PMI回落至49.3% 重回收缩区间",
   "summary": "10月中国制造业PMI为49.3%，较上月降0.8个百分点，重回荣枯线以下；新订单49.4%、新出口订单48.7%均回落。统计局称主因长假后消费高峰平淡、基础原材料转入淡季等季节性因素。",
   "decision": "内需偏弱背景下，招联应偏重稳健客群与场景分期，避免顺周期放大消费信贷风险敞口。",
