   "summary": "A股42家上市银行前三季营收4.66万亿元(+7.81%)、归母净利润1.75万亿元(+3.78%)，息差企稳与其他非息改善驱动。六大行中工行+9.97%、农行+10.84%、建行+9.8%居前。",
   "decision": "银行息差企稳、估值修复，招联股东招行基本面稳健，对招联资本与渠道协同形成支撑。",
