   "title": "中瑞自贸协定升级议定书签署 近300个税目进一步降税",
   "summary": "中国与瑞士签署自贸协定升级议定书，双方在原协定基础上分别对近300个税目进一步降低关税，零关税产品覆盖双方超99%贸易额，瑞士机床、手表、咖啡输华逐步取消关税。",
