   "summary": "在2026香港金融科技周，度小满联合港科大、HKGAI发布轩辕4.5金融增强大模型，基于自进化(RSI)技术在获客、风控、客户经营核心场景效果提升30%、成本仅为通用模型10%，为行业首个自进化金融增强大模型。",
