   "summary": "谷歌发布新一代旗舰模型Gemini 4 Carbon，在独立评测Artificial Analysis智能指数v5.0中以59分排名第一，超过Claude Opus 5.5与GPT-6 Astra；网络安全能力突出，可发现88.2%真实软件漏洞，但仅通过Fairwind计划向47家通过安全背景审查的机构开放。",
