   "summary": "陕西汉中市医保局等联合印发通知，明确自2026年10月22日起，参加职工基本医保并足额缴费的灵活就业人员、农民工、新就业形态人员，在享生育医疗费用报销基础上符合条件可申领生育津贴。",
   "decision": "生育津贴覆盖向灵活就业群体扩围，若家庭任一方属灵活就业参保，可对照汉中/所在地新规确认生育津贴申领资格，避免漏享。",
