   "title": "新生儿出生'一件事'政务集成：户口、疫苗、生育津贴一次办",
   "summary": "新生儿出生'一件事'政务服务集成办理出生登记、预防接种证、生育津贴申领等事项；按法规婴儿出生后一个月内须申报出生登记，儿童出生后一个月内须办理预防接种证。",
   "decision": "宝宝出生后须在一个月内完成户口登记与疫苗接种证办理，建议提前了解参保地'出生一件事'线上入口，备齐材料一次性办理，省时省心。",
