   "title": "《残疾预防和残疾人康复条例》等14部行政法规修改 涉一老一小保障",
   "summary": "国务院修改和废止部分行政法规，其中《残疾预防和残疾人康复条例》明确县级以上政府合理布局康复机构并纳入基本公共服务体系规划，强化'一老一小'等重点人群服务保障。",
   "decision": "条例强化康复机构布局与重点人群保障，与母婴、儿童健康服务网络衔接，可作为未来宝宝及家人康复资源的政策依据。",
