   "title": "《食品标识监督管理办法》2027年3月施行，违规婴幼儿食品禁售",
   "summary": "《食品标识监督管理办法》将于2027年3月16日施行。新规明确：实施前生产的婴幼儿配方食品，如标识违反禁止性规定（如明示暗示增强免疫力）不得继续销售；未违反的可售至保质期结束。",
   "decision": "选购“开心”口粮时注意生产日期与标签合规性，2027年3月后不合规旧货将退市。",
