   "summary": "近日湖南长沙岳麓区成功查获2处非法开展人类辅助生殖技术的地下窝点，抓获涉案人员21名。案件提示辅助生殖须走正规医疗机构渠道。",
   "decision": "生育健康无小事，任何辅助生殖需求务必认准正规资质机构，警惕地下黑产。",
