   "summary": "山东“十五五”卫生健康规划提出：实施早孕关爱行动，推广婚前孕前一体化服务；落实免费产前筛查、新生儿四种遗传代谢病免费筛查（率保持95%以上）；母婴安全赋能行动对高危孕产妇一人一档专案管理，系统管理率达97%以上。",
   "decision": "母婴安全保障体系持续完善，关注居住地孕产与新生儿筛查公共服务，为家庭育儿健康兜底。",
