   "summary": "山东省政府印发“十五五”规划通知，提出健全生育支持政策体系，落实婚育假期、育儿补贴、个税专项附加扣除，完善普惠托育服务体系，实施托育服务质量提升行动与母婴安全赋能行动计划。",
