   "title": "国家整治奶粉“多胞胎”，澳瑞佳逆势推有机版",
   "summary": "在《标签标识问答》与《食品标识监督管理办法》收紧下，婴配粉“同配方换包装套利”模式被叫停。澳瑞佳推出有机版，不做渠道分割只做门店筛选（A2版前20%门店、全国限1000家），以真产品差异应对行业分化。",
   "decision": "育儿选奶粉可借此识别“真升级”与“换壳”，优先看配方与奶源而非包装故事。",
