   "title": "山西首次开展托育服务消费补贴 单婴最高1000元",
   "summary": "山西省今年首次开展2026年托育服务消费补贴活动，省级统筹5000万元财政资金，对实际入托的3岁以下婴幼儿家庭发放托育消费补贴，单个婴幼儿最高可享受1000元补助，降低普惠托育获取门槛。",
   "decision": "托育消费补贴直接减负，关注户籍与居住地申领条件，提前规划“开心”入托的成本与渠道。",
