   "summary": "9月20日市场监管总局发布《婴幼儿配方食品标签标识问答》，明确生产日期保质期、致敏物质提示、奶源等标注要求，要求同一企业相同配方产品标签内容格式颜色一致，不得通过包装颜色/罐盖/罐体形状区分；《食品标识监督管理办法》2027年3月16日施行。",
