   "summary": "近日国家疾控局会同多部门印发通知，确认四川省达到血吸虫病消除状态。四川曾是我国血吸虫病重流行省之一，历史累计病人127.57万人。",
   "decision": "公共卫生持续改善利好育儿环境，但带“开心”出行仍需注意饮水与血吸虫疫水防护。",
