   "summary": "《绍兴市加快学前教育高质量发展第五轮行动计划(2026—2028年)》11月15日起施行：到2028年三年入园率稳定在99%以上，普惠性幼儿园、公办园在园儿童覆盖面分别达95%、85%。",
