   "summary": "《食品委托生产监督管理办法》将施行，明确委托方为食品安全第一责任人、受托方对生产行为负责；划定红线——婴幼儿配方乳粉、特医食品等特殊食品严禁委托生产，仅出口食品适用进出口监管。",
   "decision": "给宝宝选奶粉须认准“不准委托生产”的合规大厂自产品牌，规避贴牌代工风险。",
