   "summary": "医疗机构主流建议，6月龄起优先强化铁米粉/铁含量可靠米粉补铁（每日需约11mg铁），再逐步加入高铁肉泥、蔬菜泥，水果泥靠后；每次一种新食材观察2—3天。",
   "decision": "若宝宝已满6月，科学添辅食优先补铁；目前仅作育儿知识储备。",
