   "summary": "陕西省卫生健康委等6部门联合印发《促进和规范“人工智能+医疗卫生”应用发展工作方案》，明确到2027年建立一批高质量数据集和可信数据空间，形成临床专科专病垂直大模型与智能体矩阵，推动智能辅助决策广泛应用；到2030年AI辅助基层诊疗基本实现全覆盖。",
