   "title": "广西重型地中海贫血患儿出生率连续7年“零出生”",
   "summary": "广西卫健委新闻发布会透露，全区现有妇幼保健院106家、县县有危重孕产妇和危重新生儿救治中心，2026年1-9月孕产妇死亡率8.36/10万、婴儿死亡率2.24‰；重型地贫患儿出生率连续7年实现“零出生”防控目标，累计完成地贫造血干细胞移植2530例。",
   "decision": "母婴安全保障体系持续强化，宝宝“开心”落户后及时完成新生儿疾病筛查与疫苗接种，借区域优质妇幼资源护航成长。",
