   "summary": "国务院总理李强签署国务院令公布《关于修改和废止部分行政法规的决定》，对14部行政法规部分条款予以修改、4部予以废止，落实整治形式主义为基层减负、衔接机构改革精神，自公布之日起施行。",
   "decision": "行政法规批量'瘦身'为基层减负，涉及河道、地震监测、自然灾难救助等多领域，关注其对地方执行口径与营商环境的边际改善。",
