   "summary": "中共中央二十届五中全会公报发布，审议通过《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》；习近平同德国总统施泰因迈尔会谈、会见瑞士联邦主席帕姆兰等外事活动同期进行。",
   "decision": "全面从严治党纵深推进，国企/金融机构党风廉政建设持续加码，招联合规文化需同步强化。",
