   "summary": "国务院总理李强在浙江乌镇出席2026年世界互联网大会乌镇峰会开幕式并发表主旨演讲，强调互联网发展需更加突出以人为本，坚持人的主导性，让机器成为人类可信工具；需要更加可控的技术创新、更加严密的安全防范、更加充分的协同合作。",
   "decision": "“以人为本、可控”成为AI政策基调，招联智鹿等消保智能体契合该导向，可作为合规叙事支点。",
