   "summary": "市场监管总局批准发布国家标准《城市和社区可持续发展 城市服务和生活品质的指标》，共设置122项指标，覆盖经济、教育、能源、环境、健康、住房、交通、安全等19个领域，统一统计口径，并对接联合国可持续发展目标，为城市服务与居民生活品质建立可量化“度量衡”。",
