   "summary": "发改委在奋进“十五五”发布会上介绍，我国新兴支柱产业去年产值接近6万亿元，到“十五五”末有望达10万亿元以上。前三季度集成电路产量4428亿块、同比增23.3%，创新药对外技术授权交易额约1300亿美元、接近去年全年水平。",
