   "summary": "经国务院同意，国务院办公厅转发国家发展改革委《关于推动生活性服务业补短板上水平提高人民生活品质的若干意见》，11月2日对外发布，包括9方面30项举措：推动大城市加快发展老年助餐、居家照护，力争五年内覆盖80%以上社区，支持社会力量发展托育设施。",
   "decision": "“一老一小”服务供给加码，托育与养老是宝宝“开心”成长与长辈照护的利好，可关注属地普惠托育与社区助老资源。",
