   "title": "国务院推行常住地提供基本公共服务实施意见 逐步消除与户籍挂钩",
   "summary": "国务院印发《关于推行常住地提供基本公共服务的实施意见》，提出逐步消除基本公共服务与户籍挂钩因素，在随迁子女教育、公租房保障、就业地参保等方面扩大常住人口同等享有。",
   "decision": "常住人口公共服务均等化影响人才流动与消费信心，对招联用户结构与区域消费信贷需求有中长期影响。",
