   "title": "国台办：台湾是中国一部分，无权加入国际刑警组织",
   "summary": "朱凤莲强调，我们坚决反对建交国与中国台湾地区进行任何形式的官方往来，敦促欧洲议会有关人员恪守一个中国原则。关于台湾地区参与国际组织活动，必须按照一个中国原则处理，台湾作为中国的一部分，无权加入国际刑警组织，相关合作渠道已妥善安排。",
   "decision": "一个中国原则下的官方往来红线明确，涉及两岸业务合作须严格合规，避免触碰政策边界。",
