   "title": "[海外] 伊朗最高领袖警告美以：若再发动攻击 决定权在伊朗人民及其武装力量",
   "summary": "据环球时报，伊朗最高领袖穆杰塔巴10月31日向武装部队下达“重要战略指示”，警告若美以再次发动攻击，“决定冲突何时结束以及在何种条件下结束的将是伊朗人民及其武装力量”，军方已将新敌方目标清单列入打击计划。",
   "decision": "中东冲突升级风险推升油价与避险波动，间接影响国内油价与招联用户的出行/消费成本，需关注输入性通胀。",
