   "summary": "10月31日二十国集团外长会在美国亚特兰大结束，与会各国在乌克兰危机、美伊冲突和美国关税政策上分歧严重，未就地缘和经济安全问题达成共识；多名代表担忧美可能再次对伊动武及伊朗报复。",
   "decision": "多边协调机制弱化，全球贸易与能源不确定性上升，间接影响国内经济与消费预期。",
