   "summary": "国内车企10月销量数据出炉：比亚迪超49万辆同比+11%领跑，上汽43万辆紧随；零跑交付破10万居新势力首位，小鹏、小米首次站上5万辆，昊铂埃安4.2万辆，蔚来、鸿蒙智行、深蓝、极氪均超3万辆。",
   "decision": "新能源车消费仍活跃，是招联汽车金融重点场景；但销量见顶与降价内卷提示需严控车分期资质与残值风险。",
