   "summary": "发改委介绍“十五五”将重点培育集成电路、航空航天、生物医药等六大新兴支柱产业；前三季度集成电路产量4428亿块+23.3%，创新药对外授权约1300亿美元。预计期末新兴支柱产值有望翻番至10万亿元以上。",
