   "summary": "11月3日，地卫二空间技术（杭州）与阿曼兰斯有限公司签署太空人工智能协议，是中国商业航天首个星座出海、商业卫星出海最大单体项目。双方围绕“太空丝绸之路计划”合作，首批预计发射20颗卫星，由阿曼自2024年11月“阿曼星一号”成功发射后形成的一体化出海能力支撑。",
