   "summary": "11月3日8时15分，力箭二号遥二运载火箭在东风商业航天创新试验区发射升空，将千帆极轨21组卫星顺利送入预定轨道。按规划，千帆星座一期部署648颗、2026年底完成324颗在轨，此次发射后其在轨卫星总量提升至274颗，初步提供区域服务。",
