   "summary": "11月2日，2026年“中国芯”集成电路产业促进大会暨第二十一届“中国芯”优秀产品征集结果发布仪式在横琴粤澳深度合作区举行，主题“智启芯途协同共生”。大会覆盖重大创新突破、技术创新、RISC-V、EDA专项等赛道，同期成立合见工软先进芯片设计研究院、发布车控操作系统与芯片适配“产融芯链行动”，并成立港珠澳琴海上算力联盟。",
