   "summary": "据上证报，云南锗业控股子公司云南鑫耀与应用光电公司AOI签订长期供货协议，2027年至2031年每年采购18万片4英寸N型磷化铟衬底，五年总量90万片。磷化铟是800G/1.6T高速光模块关键基底，供需缺口超70%，价格年内大幅上涨。",
