   "summary": "北京太空算力创新中心发布全球首个天地一体化太空算力云平台，覆盖40余颗卫星算力资源，与CPU/GPU/NPU等地面算力统一纳管与池化调度，支持大模型推理的星地协同；已与百度智能云百舸平台互联互通。",
   "decision": "太空算力从概念走向平台化，长期或重塑AI算力供给格局，招联可关注低成本算力对智能风控/营销的降本潜力。",
