   "summary": "11月2日至5日，2026“互联网之光”博览会在乌镇举行，以“智能互联、智见未来”为主题，首次全方位展示“智能互联网”，设置空天地海、智能涌现、人机共生等六大展区，阿里、腾讯、科大讯飞等发布最新大模型，华为昇腾、中兴、曙光超节点集中亮相。",
