   "summary": "自然资源部例行发布会透露，经对共伴生、低品位战略性矿产再评价，我国镓、锗、铟等13种矿产保有资源量显著增加，其中铼增加超两倍、金相当于新增50个大型矿床，有力支撑新一轮找矿突破战略行动。",
   "decision": "关键战略资源自给提升，增强科技与国防产业链安全，与家庭及招联业务的长期韧性正相关。",
