   "title": "2026“中国芯”大会横琴启幕 聚焦AI算力与端侧智能",
   "summary": "11月1日至4日，2026“中国芯”集成电路产业促进大会暨第二十一届“中国芯”优秀产品征集结果发布在横琴及澳门举办，以“智启芯途 协同共生”为主题，探讨AI先进计算芯片能效瓶颈、端侧智能与汽车芯片，并设置芯片出海与粤澳投融资对接论坛。",
   "decision": "国产芯片生态与出海加速，招联可关注端侧智能芯片在金融终端/风控设备的合规应用机会。",
