   "summary": "原集微科技发布基于二维原子层半导体的集成电路标准工艺库及原型器件，正式推出4英寸二硫化钼晶圆的二维原型芯片产品并开放对外代工流片服务，补齐国内二维集成电路工艺标准化短板，打通从设计到制造的工程闭环。",
   "decision": "二维半导体工程化推进国产芯片路线多元化，利好科技产业链自主可控，对招联数字化采购可选空间有长期意义。",
