   "summary": "“明珠星座计划”以建设GW级天基算力基础设施为目标，推动智能计算由地面向近地轨道延伸，按“技术验证—能力迭代—规模组网”渐进路径形成全球覆盖、大小星协同的天基智能服务网络，由上海企业作为链主单位推进。",
   "decision": "天基算力拓展AI基础设施边界，长期利好低成本算力供给，招联可关注其对金融云与灾备架构的潜在价值。",
