   "summary": "中国工程院院士张旭团队开发直觉神经网络INN，更好模拟大脑感觉运动皮层感知认知融合；基于该模型的类脑计算系统仅6千瓦功耗即可支撑1153个X86核心、每秒135万词元推理，处理非结构化数据时能耗优势达A100的18倍。",
   "decision": "类脑算力能效跃迁，长期或重塑AI推理成本结构，招联可将其作为风控/营销推理降本的技术跟踪方向。",
