   "summary": "2026大湾区科学论坛在广州开幕，发布《颠覆性技术前瞻2026》遴选40项前沿技术，多模态原生统一模型位列重点方向，覆盖AI材料设计、超快充电池等；同步推出40条支持科创中心举措，扶持AI、集成电路、新能源、低空经济。",
