   "summary": "据多方消息，Meta与国内机器人企业傅里叶联合开发人形机器人原型Max，第二代版本同步启动研发，是Meta机器人业务成立以来实质性进展；与此同时国内具身智能企业密集推进芯片与整机落地。",
