   "summary": "据券商研报，人形机器人模型端发展路线已从VLA（视觉-语言-动作）转向WLA（世界-语言-动作），物理AI加速演进打通“硬件部署—真实物理交互”链路，机器人不再仅理解眼前画面，而是基于世界模型规划动作。",
   "decision": "具身智能通用化再进一步，招联可关注机器人客服/大堂引导在安全合规边界内的应用可行性。",
