   "summary": "英伟达在SEMICON West 2026展示下一代共封装光学技术OOI，将光引擎直接集成到承载GPU的硅中介层，光电转换进一步向芯片内核靠拢，为超大规模AI集群提供新互联思路，暂无商业化时间表。",
